{
	"schemaVersion": 1,
	"complete": false,
	"rules": [
		{
			"id": "R-01",
			"statement": "The subtotal in minor units is the sum, over every line, of unitPriceMinor multiplied by quantity; no further rounding applies because every input is already an integer minor-unit amount."
		},
		{
			"id": "R-02",
			"statement": "A basket qualifies for a discount once its subtotal is greater than or equal to 5000 minor units (the threshold is inclusive); the discount equals 10% of the subtotal rounded down to the nearest whole minor unit, and is exactly zero below the threshold."
		},
		{
			"id": "R-03",
			"statement": "The discount computed under R-02 is capped at 2000 minor units: once 10% of the subtotal would exceed 2000, the discount actually applied stays at exactly 2000, so a bigger basket above that point earns no additional discount."
		},
		{
			"id": "R-04",
			"statement": "Shipping is a flat 499 minor units, waived down to 0 only when the subtotal AFTER the R-02/R-03 discount has been subtracted is greater than or equal to 10000 minor units; the comparison inclusively tests the discounted figure, never the raw subtotal."
		},
		{
			"id": "R-05",
			"statement": "The total in minor units equals the subtotal minus the capped discount, plus shipping, computed strictly in that order: discount first, then shipping evaluated against the discounted figure, then the two summed."
		},
		{
			"id": "R-06",
			"statement": "An order is invalid whenever any line's quantity is not strictly greater than zero (zero or negative); each such line produces its own error entry carrying a stable machine-readable code, QUANTITY_NOT_POSITIVE, and that line's sku."
		}
	]
}

/**
 * The conformance suite. This file is YOURS to write.
 *
 * Contract:
 *   - `RULES` lists the rule ids this suite checks. Every id must be declared in `spec/spec.json`.
 *   - `checkConformance(subject)` is handed an implementation's module namespace — `subject.quote`,
 *     `subject.validate` — and returns an array of `{ rule, ok, detail }`, with at least one entry per declared
 *     rule. `ok: false` means the subject violates that rule; `detail` says what was observed.
 *   - Throwing is allowed and counts as rejecting the subject.
 *   - Never import anything from `candidates/`. Comparing an implementation against the oracle is not a
 *     conformance suite; it is a diff.
 */
export const RULES = ["R-01", "R-02", "R-03", "R-04", "R-05", "R-06"];

function order(lines) {
	return { currency: "GBP", lines };
}
function line(sku, unitPriceMinor, quantity) {
	return { sku, unitPriceMinor, quantity };
}

export function checkConformance(subject) {
	const results = [];

	// R-01: the subtotal is the sum of unitPriceMinor * quantity across every line.
	{
		const o = order([line("A", 1234, 2), line("B", 999, 3)]);
		const expectedSubtotal = 1234 * 2 + 999 * 3;
		const q = subject.quote(o);
		const ok = q.subtotalMinor === expectedSubtotal;
		results.push({ rule: "R-01", ok, detail: `subtotalMinor=${q.subtotalMinor}, expected=${expectedSubtotal}` });
	}

	// R-02: 10% of the subtotal, floored, and only earned at/above the 5000 threshold (inclusive).
	{
		const atThreshold = subject.quote(order([line("A", 5000, 1)]));
		const okAt = atThreshold.discountMinor === 500;
		const under = subject.quote(order([line("A", 4999, 1)]));
		const okUnder = under.discountMinor === 0;
		const rounding = subject.quote(order([line("A", 5005, 1)]));
		const okRound = rounding.discountMinor === 500; // floor(500.5) = 500
		const ok = okAt && okUnder && okRound;
		results.push({
			rule: "R-02",
			ok,
			detail: `at5000=${atThreshold.discountMinor}(exp 500), at4999=${under.discountMinor}(exp 0), at5005=${rounding.discountMinor}(exp 500 via floor)`,
		});
	}

	// R-03: the discount is capped at 2000 — a bigger basket past that point earns no more.
	{
		const atCapBoundary = subject.quote(order([line("A", 20000, 1)])); // raw 10% == 2000
		const okBoundary = atCapBoundary.discountMinor === 2000;
		const pastCap = subject.quote(order([line("A", 30000, 1)])); // raw 10% == 3000
		const okPastCap = pastCap.discountMinor === 2000;
		const wayPastCap = subject.quote(order([line("A", 100000, 1)])); // raw 10% == 10000
		const okWayPast = wayPastCap.discountMinor === 2000;
		const ok = okBoundary && okPastCap && okWayPast;
		results.push({
			rule: "R-03",
			ok,
			detail: `at20000=${atCapBoundary.discountMinor}, at30000=${pastCap.discountMinor}, at100000=${wayPastCap.discountMinor} (all must equal the 2000 cap)`,
		});
	}

	// R-04: shipping is 499 unless the DISCOUNTED subtotal is >= 10000, in which case it is 0.
	{
		const small = subject.quote(order([line("A", 1000, 1)]));
		const okSmall = small.shippingMinor === 499;
		// subtotal 11112 -> discount floor(1111.2)=1111 -> discounted 10001 >= 10000 -> free
		const free = subject.quote(order([line("A", 11112, 1)]));
		const okFree = free.shippingMinor === 0;
		// subtotal 10500 (raw >= 10000) -> discount floor(1050)=1050 -> discounted 9450 < 10000 -> still charged.
		// Proves the comparison uses the discounted figure, not the raw subtotal.
		const mixed = subject.quote(order([line("A", 10500, 1)]));
		const okMixed = mixed.shippingMinor === 499;
		const ok = okSmall && okFree && okMixed;
		results.push({
			rule: "R-04",
			ok,
			detail: `small(1000)=${small.shippingMinor}(exp 499), discounted-crosses(11112)=${free.shippingMinor}(exp 0), raw-crosses-only(10500)=${mixed.shippingMinor}(exp 499)`,
		});
	}

	// R-05: total = (subtotal - discount) + shipping, in that order.
	{
		const q = subject.quote(order([line("A", 11112, 1)]));
		const expectedTotal = q.subtotalMinor - q.discountMinor + q.shippingMinor;
		const ok = q.totalMinor === expectedTotal;
		results.push({
			rule: "R-05",
			ok,
			detail: `totalMinor=${q.totalMinor}, expected (subtotal-discount)+shipping=${expectedTotal}`,
		});
	}

	// R-06: a non-positive quantity on any line is rejected with a machine-readable code.
	{
		const bad = order([line("A", 500, 0), line("B", 500, -1), line("C", 500, 2)]);
		const v = subject.validate(bad);
		const shapeOk = Boolean(v) && v.ok === false && Array.isArray(v.errors) && v.errors.length === 2;
		const codesOk =
			shapeOk && v.errors.every((e) => typeof e.code === "string" && e.code.length > 0 && typeof e.sku === "string");
		const good = subject.validate(order([line("A", 500, 1)]));
		const goodOk = Boolean(good) && good.ok === true && Array.isArray(good.errors) && good.errors.length === 0;
		const ok = Boolean(shapeOk && codesOk && goodOk);
		results.push({
			rule: "R-06",
			ok,
			detail: `bad-order ok=${v?.ok}, errors=${JSON.stringify(v?.errors)}; good-order ok=${good?.ok}`,
		});
	}

	return results;
}

